Here is the commit message:
Bluetooth: hci_event: fix potential UAF in SSP passkey
 handlers

hci_conn lookup and field access must be covered by hdev lock in
hci_user_passkey_notify_evt() and hci_keypress_notify_evt(), otherwise
the connection can be freed concurrently.

Extend the hci_dev_lock critical section to cover all conn usage in both
handlers.

Keep the existing keypress notification behavior unchanged by routing
the early exits through a common unlock path.

Fixes: 92a25256f142 ("Bluetooth: mgmt: Implement support for passkey notification")
Cc: stable@vger.kernel.org
Signed-off-by: Shuvam Pandey <shuvampandey1@gmail.com>
Signed-off-by: Luiz Augusto von Dentz <luiz.von.dentz@intel.com>

Here is the root cause:
The bug arises because `hci_user_passkey_notify_evt` and `hci_keypress_notify_evt` in `net/bluetooth/hci_event.c` accessed the `hci_conn` structure (via lookup and field modifications) without holding the `hdev` lock. Without this lock, another thread could concurrently free the connection (e.g., upon disconnection or timeout), leading to a use-after-free when the handlers subsequently dereference the connection pointer or modify its fields.

Here is the patch:

 static void hci_user_passkey_notify_evt(struct hci_dev *hdev, void *data,
 					struct sk_buff *skb)
 {
 	struct hci_ev_user_passkey_notify *ev = data;
 	struct hci_conn *conn;

 	bt_dev_dbg(hdev, "");

+	hci_dev_lock(hdev);
+
 	conn = hci_conn_hash_lookup_ba(hdev, ACL_LINK, &ev->bdaddr);
 	if (!conn)
-		return;
+		goto unlock;

 	conn->passkey_notify = __le32_to_cpu(ev->passkey);
 	conn->passkey_entered = 0;

 	if (hci_dev_test_flag(hdev, HCI_MGMT))
 		mgmt_user_passkey_notify(hdev, &conn->dst, conn->type,
 					 conn->dst_type, conn->passkey_notify,
 					 conn->passkey_entered);
+
+unlock:
+	hci_dev_unlock(hdev);
 }

 static void hci_keypress_notify_evt(struct hci_dev *hdev, void *data,
 				    struct sk_buff *skb)
 {
 	struct hci_ev_keypress_notify *ev = data;
 	struct hci_conn *conn;

 	bt_dev_dbg(hdev, "");

+	hci_dev_lock(hdev);
+
 	conn = hci_conn_hash_lookup_ba(hdev, ACL_LINK, &ev->bdaddr);
 	if (!conn)
-		return;
+		goto unlock;

 	switch (ev->type) {
 	case HCI_KEYPRESS_STARTED:
 		conn->passkey_entered = 0;
-		return;
+		goto unlock;

 	case HCI_KEYPRESS_ENTERED:
 		conn->passkey_entered++;
 		break;

 	case HCI_KEYPRESS_ERASED:
 		conn->passkey_entered--;
 		break;

 	case HCI_KEYPRESS_CLEARED:
 		conn->passkey_entered = 0;
 		break;

 	case HCI_KEYPRESS_COMPLETED:
-		return;
+		goto unlock;
 	}

 	if (hci_dev_test_flag(hdev, HCI_MGMT))
 		mgmt_user_passkey_notify(hdev, &conn->dst, conn->type,
 					 conn->dst_type, conn->passkey_notify,
 					 conn->passkey_entered);
+
+unlock:
+	hci_dev_unlock(hdev);
 }



